package com.bank.jvm;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Processes trades. Short-lived fee objects stress the Young Gen.
// Optionally retaining trades stresses the Old Gen (demonstrates a leak).
class SettlementProcessor {
    private static final Logger log = Logger.getLogger(SettlementProcessor.class.getName());
    private static final BigDecimal FEE_RATE = new BigDecimal("0.0005");

    private final List<Trade> retained = new ArrayList<>();  // grows if retain=true

    BigDecimal process(List<Trade> trades, boolean retain) {
        BigDecimal totalFees = BigDecimal.ZERO;
        for (Trade t : trades) {
            // Short-lived object: created, used, then becomes garbage (Young Gen churn).
            BigDecimal fee = t.amount().multiply(FEE_RATE).setScale(2, RoundingMode.HALF_UP);
            totalFees = totalFees.add(fee);
            if (retain) {
                retained.add(t);  // keeps references alive → Old Gen pressure
            }
        }
        log.info(() -> "Processed " + trades.size() + " trades, totalFees=Rs." + totalFees);
        return totalFees;
    }

    int retainedCount() { return retained.size(); }
}
