package com.bank.jvm;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class JvmInternalsDemo {
    private static final Logger log = Logger.getLogger(JvmInternalsDemo.class.getName());

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        log.info(() -> "Settlement for " + rajesh.getHolderName());

        List<Trade> trades = buildTrades(500_000);  // half a million trades
        SettlementProcessor processor = new SettlementProcessor();

        printHeap("Before processing");
        BigDecimal fees = processor.process(trades, false); // short-lived objects only
        printHeap("After processing (no retain)");

        log.info(() -> "Total settlement fees: Rs." + fees);
        log.info(() -> "Retained objects: " + processor.retainedCount());

        log.info("To inspect this JVM, run in another terminal:");
        log.info("  jstack <pid>       # thread dump");
        log.info("  jmap -dump:live,format=b,file=heap.hprof <pid>   # heap dump");
    }

    private static List<Trade> buildTrades(int n) {
        List<Trade> list = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            list.add(new Trade("T" + i, "SAV2001", "RELIANCE", 100, new BigDecimal("2450")));
        }
        return list;
    }

    private static void printHeap(String label) {
        Runtime rt = Runtime.getRuntime();
        long usedMb = (rt.totalMemory() - rt.freeMemory()) / (1024 * 1024);
        long maxMb = rt.maxMemory() / (1024 * 1024);
        log.info(() -> label + " — heap used: " + usedMb + " MB / max: " + maxMb + " MB");
    }
}
